-- 한 건씩 고치면

@Test
@Transactional
void 한_건씩() {
    em.clear();
    long n = counter.count(() -> {
        List<Member> members = memberRepository.findAll();
        for (Member m : members) {
            if (m.getAge() >= 20) m.setAge(m.getAge() + 1);
        }
        em.flush();
    });
    System.out.println("쿼리 " + n + "개");
}

