-- 여기서 문제가 시작된다

@Test
@Transactional
void 어긋난다() {
    em.clear();
    Member before = memberRepository.findByUsername("m3").orElseThrow();
    System.out.println("고치기 전 객체: " + before.getAge());

    memberRepository.bulkAgePlus(20);

    System.out.println("고친 뒤 객체:   " + before.getAge());

    Member again = memberRepository.findByUsername("m3").orElseThrow();
    System.out.println("다시 읽은 객체: " + again.getAge());
    System.out.println("같은 객체?      " + (before == again));
}

