    em.clear();
    long a = counter.count(() ->
            memberRepository.deleteAll());
    setUpAgain();
    em.clear();
    long b = counter.count(() ->
            memberRepository.bulkDelete(999));
    System.out.println("deleteAll  " + a + "개");
    System.out.println("bulkDelete " + b + "개");
}

