@Test
@Transactional
void 버전() {
    Long v0 = (Long) em.createNativeQuery(
            "select version from item where item_id = 1").getSingleResult();
    memberRepository.decrease(1L);
    Long v1 = (Long) em.createNativeQuery(
            "select version from item where item_id = 1").getSingleResult();
    System.out.println("버전: " + v0 + " -> " + v1);
}

